import React from 'react';
import '../App.css';

const EmployeeDashboard = ({ user }) => {
    return (
        <div className="container mt-5">
            <div className="card bw-card">
                <div className="card-header bw-header">
                    <h3>Welcome to EMS</h3>
                </div>
                <div className="card-body">
                    <h5 className="card-title">Employee Information</h5>
                    <p className="card-text"><strong>ID:</strong> {user.id}</p>
                    <p className="card-text"><strong>Name:</strong> {user.name}</p>
                    <p className="card-text"><strong>Username:</strong> {user.username}</p>
                    <p className="card-text"><strong>Email:</strong> {user.email}</p>
                    <p className="card-text"><strong>Role:</strong> {user.role}</p>
                    <hr/>
                    <p>You have limited access. Contact admin for changes.</p>
                </div>
            </div>
        </div>
    );
};

export default EmployeeDashboard;
